  @Test
  public void testDuplicatePropertyFails() throws IOException, XMLStreamException {
    final Path path =
      Paths.get(
        Common.TEST_DATA_DIR,
        "Xml",
        "Expected",
        "childA",
        "minimal.xml");

    final String text =
      new String(Files.readAllBytes(path), StandardCharsets.UTF_8);

    // We cut the element of the property out of the recorded example and put it
    // in a second time, just before the closing tag of the instance.
    final int start = text.indexOf("<number>");

    final String property;
    if (start >= 0) {
      final int end = text.indexOf("</number>", start);
      property = text.substring(start, end + 9);
    } else {
      // The element is written self-closing in the example, an empty list being
      // the usual reason. We write that very element out ourselves.
      property = "<number/>";
    }

    final int insertionIndex =
      text.lastIndexOf("</childA>");

    if (insertionIndex < 0) {
      throw new IllegalStateException(
        "We expect the recorded example to contain the closing tag "
          + "</childA>" + ", but it does not: " + path);
    }

    final String brokenText =
      text.substring(0, insertionIndex) + property + text.substring(insertionIndex);

    final XMLInputFactory xmlInputFactory = XMLInputFactory.newInstance();
    final XMLEventReader xmlReader =
      xmlInputFactory.createXMLEventReader(new StringReader(brokenText));

    XmlCommon.DeserializeException exception = null;

    try {
      Xmlization.Deserialize.deserializeChildA(xmlReader);
    } catch (XmlCommon.DeserializeException observedException) {
      exception = observedException;
    }

    if (exception == null) {
      fail(
        "Expected an exception when the property "
          + "number"
          + " is given twice, but got none");
    }
  } // public void testDuplicatePropertyFails

  /**
   * Read the first recorded example of ChildA with the content of
   * the element {@code xmlName} replaced by {@code text}.
   */
  private static ChildA readWith(String xmlName, String text)
    throws IOException, XMLStreamException {
    final Path searchPath =
      Paths.get(Common.TEST_DATA_DIR, "Xml", "Expected", "childA");
    final List<Path> paths = Common.findPaths(searchPath, ".xml");

    if (paths.isEmpty()) {
      fail(
        "Expected at least one recorded example of childA, but got none");
    }

    final String original =
      new String(Files.readAllBytes(paths.get(0)), StandardCharsets.UTF_8);

    final int start = original.indexOf("<" + xmlName + ">") + xmlName.length() + 2;
    final int end = original.indexOf("</" + xmlName + ">");

    final String patched =
      original.substring(0, start) + text + original.substring(end);

    final XMLInputFactory xmlInputFactory = XMLInputFactory.newInstance();
    final XMLEventReader xmlReader =
      xmlInputFactory.createXMLEventReader(new StringReader(patched));

    return Xmlization.Deserialize.deserializeChildA(xmlReader);
  }

